codeExamples.code:
const element = <h1 className="title">Hello, world!</h1>;

// Roughly compiles to:
// const element = React.createElement(
//   "h1",
//   { className: "title" },
//   "Hello, world!"
// );

function UserCard() {
  return (
    <>
      <h2>Ada Lovelace</h2>
      <p>Mathematician</p>
    </>
  );
